'use client';
import dynamic from 'next/dynamic';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { motion } from 'framer-motion';

const HeroThreeJS = dynamic(() => import('./HeroThreeJS'), { ssr: false });

const HeroScene = () => {
  const pathname = usePathname();
  const isWebGLAvailable = typeof window.WebGLRenderingContext !== 'undefined';
  const isReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  return (
    <div className="hero">
      {isWebGLAvailable && !isReducedMotion ? (
        <HeroThreeJS />
      ) : (
        <svg width="100%" height="100%" viewBox="0 0 100 100">
          <circle cx="50" cy="50" r="40" fill="blue" />
        </svg>
      )}
      <nav>
        <Link href="/finance" className={pathname === '/finance' ? 'active' : ''}>Overview</Link>
        <Link href="/finance/investments" className={pathname === '/finance/investments' ? 'active' : ''}>Investments</Link>
        <Link href="/finance/debt" className={pathname === '/finance/debt' ? 'active' : ''}>Debt</Link>
        <Link href="/finance/tracker" className={pathname === '/finance/tracker' ? 'active' : ''}>Tracker</Link>
        <Link href="/finance/learning" className={pathname === '/finance/learning' ? 'active' : ''}>Learning</Link>
        <Link href="/finance/settings">Settings</Link>
      </nav>
    </div>
  );
};

export default HeroScene;
